const R=window.DBI_RESEARCH;
function evidenceViews(){return '<div class="view-switch" role="group" aria-label="Cách xem bằng chứng">'+[['list','Điểm gộp từ Excel'],['matrix','So sánh theo tiêu chí'],['annual','Đối chiếu theo năm']].map(([v,t])=>'<button class="button '+(S.evidenceView===v?'primary':'')+'" data-view="'+v+'" aria-pressed="'+(S.evidenceView===v)+'">'+t+'</button>').join('')+'</div>';}
function annualRows(){const query=normalizeSearch(S.search.trim());return R.records.filter(r=>(S.bank==='all'||S.bank===r.bank)&&(S.year==='all'||r.year===Number(S.year))&&(S.pillar==='all'||r.pillar===Number(S.pillar))&&(S.reviewState==='all'||(S.reviewState==='scored'?r.level!==null:S.reviewState==='candidate'?r.level===null&&r.candidates.length:S.reviewState==='reviewed'?r.status==='Chưa đủ căn cứ':S.reviewState==='unreviewed'?r.status==='Chưa đối chiếu mức':r.level===null&&!r.na))&&(S.level==='all'||(S.level==='missing'?r.level===null&&!r.na:S.level==='na'?r.na:r.level===Number(S.level)))&&(!query||normalizeSearch([r.bank,bank(r.bank).label,r.code,r.sourceCode,r.name,r.year,r.reason,...r.citations.flatMap(c=>[c.excerpt,c.transcription??'']),...r.candidates.map(c=>c.excerpt)].join(' ')).includes(query)));}
function annualEvidence(){return evidenceViews()+'<div class="evidence-controls"><input id="evidence-search" type="search" class="search-field" aria-label="Tìm bằng chứng theo năm" placeholder="Tìm mã, tiêu chí, năm, nội dung…" value="'+esc(S.search)+'"><select id="annual-year" aria-label="Năm hoạt động">'+opts([['all','Cả 3 năm'],['2023','2023'],['2024','2024'],['2025','2025']],S.year)+'</select><select id="review-state" aria-label="Trạng thái đối chiếu">'+opts([['all','Tất cả trạng thái'],['scored','Đã đối chiếu mức'],['candidate','Có tài liệu liên quan'],['pending','Tất cả dòng chưa chấm'],['reviewed','Chưa đủ căn cứ'],['unreviewed','Chưa đối chiếu mức']],S.reviewState)+'</select><select id="pillar-filter" aria-label="Trụ cột">'+pOpts()+'</select><select id="level-filter" aria-label="Mức đạt theo năm">'+opts([['all','Tất cả mức'],['missing','Chưa chấm mức'],['na','NA · Không áp dụng'],...Array.from({length:6},(_,i)=>[String(i),'Mức '+i])],S.level)+'</select></div><section class="card"><div id="evidence-results"></div></section><div style="height:20px"></div>';}
function renderAnnualResults(){const rows=annualRows(),size=15,count=Math.max(1,Math.ceil(rows.length/size));S.evidencePage=Math.min(S.evidencePage,count);const start=(S.evidencePage-1)*size;
 $('#evidence-results').innerHTML=(rows.length?'<div class="evidence-table-wrap"><table class="evidence-table"><thead><tr><th>NGÂN HÀNG / NĂM</th><th>TIÊU CHÍ</th><th>MỨC THEO NĂM</th><th>NGUỒN / TRẠNG THÁI</th></tr></thead><tbody>'+rows.slice(start,start+size).map(r=>'<tr data-annual-id="'+R.records.indexOf(r)+'" tabindex="0" role="button" aria-label="Xem đối chiếu '+esc(r.bank)+' '+r.year+' '+esc(r.code)+'"><td>'+bname(bank(r.bank))+'<small class="annual-year-label">'+r.year+'</small></td><td class="criterion">'+esc(r.name)+'<small>'+esc(r.code)+' · '+D.pillars[r.pillar]+'</small></td><td><span class="level '+(r.level===null?'zero':'')+'">'+(r.na?'NA':r.level===null?'— · Chưa chấm':'Mức '+r.level)+'</span></td><td>'+ (r.citations.length?'<b>'+(r.level===null?'Chưa đủ bằng chứng':'Đã đối chiếu tài liệu')+'</b><div class="excerpt">'+esc(r.citations.map(c=>reportTitle(c)+' · trang PDF '+c.page).join('; '))+'</div>':'<b>Chưa chấm mức</b><div class="excerpt">'+(r.candidates.length?r.candidates.length+' tài liệu liên quan':'Chưa tìm đủ dẫn chứng')+'</div>')+'</td></tr>').join('')+'</tbody></table></div>':'<div class="no-results">Không tìm thấy bản ghi theo năm phù hợp.</div>')+'<div class="pagination"><span>'+(rows.length?start+1:0)+'–'+Math.min(start+size,rows.length)+' / '+rows.length+' bản ghi</span><div><button id="prev" '+(S.evidencePage<=1?'disabled':'')+'>←</button><span>Trang '+S.evidencePage+' / '+count+'</span><button id="next" '+(S.evidencePage>=count?'disabled':'')+'>→</button></div></div>';
 $('#prev').onclick=()=>{S.evidencePage--;renderAnnualResults();};$('#next').onclick=()=>{S.evidencePage++;renderAnnualResults();};
 document.querySelectorAll('[data-annual-id]').forEach(el=>{el.onclick=()=>openAnnual(Number(el.dataset.annualId));el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};});
}
function reportTitle(c){const report=R.reports.find(r=>r.id===c.reportId);return report?report.type+' · '+report.year:c.reportId;}
function citationHTML(c,candidate=false){const url=c.url.replace(/#.*$/,'')+'#page='+c.page,title=reportTitle(c);return '<div class="review-citation '+(candidate?'candidate':'')+'"><a class="link" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(title)+' · trang PDF '+c.page+(c.printedPage?' · trang in '+esc(c.printedPage):'')+' ↗</a><small>'+(candidate?'Chưa đủ bằng chứng':'Năm hoạt động '+c.year)+'</small><blockquote>'+esc(c.transcription??c.excerpt)+'</blockquote></div>';}
function openAnnual(id){const r=R.records[id],rubric=R.rubrics?.find(c=>c.code===r.code);$('#dialog-content').innerHTML='<div class="dialog-bank">'+bname(bank(r.bank))+'</div><div class="eyebrow">NĂM '+r.year+' · '+esc(r.code)+'</div><h2>'+esc(r.name)+'</h2><span class="level '+(r.level===null?'zero':'')+'">'+(r.na?'NA · Không áp dụng':r.level===null?'Chưa chấm · Cần đối chiếu':'Mức '+r.level+' · Quy đổi '+R.policy.conversion[r.level]+'%')+'</span><h3>Lý do đối chiếu</h3><p class="detail-text">'+esc(r.level===null&&!r.citations.length?'Chưa đủ bằng chứng xác định mức đạt cho năm '+r.year+'.':r.reason)+'</p>'+(r.citations.length?'<h3>'+(r.level===null?'Nguồn tài liệu · Chưa đủ bằng chứng':'Dẫn chứng đã đối chiếu')+'</h3>'+r.citations.map(c=>citationHTML(c)).join(''):'')+(rubric?'<h3>Mô tả thang trưởng thành</h3><div class="review-rubric">'+rubric.levels.map((t,i)=>'<details '+(r.level===i+1?'open':'')+'><summary>Mức '+(i+1)+'</summary><p>'+esc(t)+'</p></details>').join('')+'</div>':'')+(r.candidates.length?'<h3>Tài liệu liên quan</h3>'+r.candidates.map(c=>citationHTML(c,true)).join(''):'');$('#evidence-dialog').showModal();}
function pooledReview(e){const annual=R.records.filter(r=>r.bank===e.bank&&r.code===e.code&&r.level!==null);return '<h3>Bằng chứng theo năm</h3>'+annual.map(a=>'<div class="review-year"><b>'+a.year+' · Mức '+a.level+'</b><p>'+esc(a.reason)+'</p>'+a.citations.map(c=>citationHTML(c)).join('')+'</div>').join('')+'<button class="button" data-open-annual="'+esc(e.bank)+'" data-code="'+esc(e.code)+'">Tra cứu cả 3 năm ↗</button>';}
function policyPanel(){return card('Quy tắc chấm điểm','Phương pháp áp dụng từ 19/10/2026 · Giai đoạn 2023–2025','<div class="review-policy"><p><b>Điểm gộp:</b> chọn mức cao nhất được bằng chứng chứng minh đầy đủ trong giai đoạn 2023–2025 sau khi rà soát tài liệu liên quan. Phản ánh mức đã thể hiện trong giai đoạn; không phải hiện trạng cuối năm 2025 hoặc trung bình ba năm.</p><p><b>Thang đo:</b> mức 1–5 theo mô tả từng tiêu chí; cần nguồn, trang PDF, trích đoạn, lý do và người/ngày duyệt. Quy đổi 0/1/2/3/4/5 → 0/0/25/50/75/100%.</p><p><b>Tính điểm:</b> lấy trung bình các tiêu chí áp dụng trong từng trụ cột, rồi trung bình đều 6 trụ cột, mỗi trụ cột trọng số 1/6.</p><p><b>Mức 0:</b> chỉ chốt sau khi có nhật ký rà soát đủ tài liệu liên quan và chưa tìm đủ bằng chứng đáp ứng mức 1; vẫn tính trong mẫu số. Không khẳng định ngân hàng không triển khai.</p><p><b>Chưa chấm / NA:</b> chưa đủ căn cứ giữ trống, không đổi thành 0. NA phải có lý do không áp dụng trong đúng phạm vi và được duyệt; loại khỏi mẫu số. Thiếu công bố không phải NA.</p><p><b>Điểm hoàn chỉnh:</b> cần đủ mọi tiêu chí áp dụng của cả 6 trụ cột. Không có tiêu chí áp dụng ở một trụ cột thì tổng điểm không xác định. Chỉ so sánh YoY khi cả hai năm đủ dữ liệu và cùng phạm vi, phương pháp, mẫu áp dụng.</p><p><b>Phiên bản điểm hiện tại:</b> lưu bộ mức gộp từ Excel làm kết quả sơ bộ; cập nhật mức theo quy tắc trên khi hồ sơ bằng chứng được duyệt.</p></div>');}


function annualCSV(rows,name='DBI_Doi_chieu_theo_nam.csv'){csvDownload([['Ngân hàng','Năm hoạt động','Mã chuẩn','Mã Excel','Tiêu chí','Mức theo năm','Quy đổi (%)','NA','Trạng thái','Lý do','Tài liệu','URL','Trang PDF','Trang in','Trích đoạn đã đối chiếu','Ngày đối chiếu','Vị trí gợi ý chưa xác nhận'],...rows.map(r=>[bank(r.bank).label,r.year,r.code,r.sourceCode,r.name,r.level,r.level===null?'':R.policy.conversion[r.level],r.na?'Có':'',r.status,r.reason,r.citations.map(c=>c.reportId).join(' | '),r.citations.map(c=>c.url).join(' | '),r.citations.map(c=>c.page).join(' | '),r.citations.map(c=>c.printedPage).join(' | '),r.citations.map(c=>c.transcription??c.excerpt).join(' | '),r.reviewDate,r.candidates.map(c=>c.reportId+' trang PDF '+c.page).join(' | ')])],name);}
function reviewedPooledCSV(){csvDownload([['Ngân hàng','Mã chuẩn','Mã Excel','Tiêu chí','Mức gộp cũ','Bằng chứng cũ','URL cũ','Trạng thái rà soát','Năm đã đối chiếu','Mức đối chiếu theo năm','Nguồn bổ sung','Trang PDF bổ sung','Trích đoạn bổ sung','Lưu ý'],...D.evidence.map(e=>{const r=R.pooled.find(r=>r.bank===e.bank&&r.code===e.code);return [e.bank,e.code,e.sourceCode,e.name,e.level,e.text,e.urls.join(' | '),r.status,r.verifiedYears.join(' | '),r.reviewedLevels.map(a=>a.year+': '+a.level).join(' | '),r.citations.map(c=>c.url).join(' | '),r.citations.map(c=>c.reportId+': '+c.page).join(' | '),r.citations.map(c=>c.transcription??c.excerpt).join(' | '),r.reason];})],'DBI_Ra_soat_diem_gop.csv');}
function downloadPolicy(){csvDownload([['Mục','Quy tắc'],...Object.entries(R.policy).map(([k,v])=>[k,typeof v==='object'?JSON.stringify(v):v])],'DBI_Quy_tac_2026-10-19.csv');}
function bindReview(){if(S.page==='evidence'&&S.evidenceView==='annual'){for(const [id,key] of [['annual-year','year'],['review-state','reviewState']])$('#'+id).onchange=e=>{S[key]=e.target.value;S.evidencePage=1;renderAnnualResults();};}}
